      "FIBRA QUE ALIMENTA O SPLITTER 1X8 COM DIVERSOS DEFEITOS E PROBLEMAS NO CABO NO ENLACE ENTRE O SPLITTER 1X4 E O 1X8.\nFOI FEITO ALINHAMENTO DA FIBRA QUE SAI DO SPLITTER 1X4 DA AVENIDA FREDERICO AUGUSTO RITTER E ALIMENTA O SPLITTER 1X8 NA AV JOSÉ BRAMBILA ESQUINA COM AV GENERAL FLORES DA CUNHA. FOI FEITA UMA ROTA NOVA, LANÇADO CABO 24 F.O NOVO, MAS NO DIA DO ALINHAMENTO ENCONTRAMOS O CABO NOVO ROMPIDO DEVIDO UMA TROCA DE POSTES NA RUA CAÍ ESQUINA COM AV CAPITÃO GARIBALDI, LANÇAMOS 150 METROS DE CABO 24 E FIZEMOS DUAS CAIXAS NOVAS COM 24 FUSÕES RETAS. APÓS SEGUIMOS COM O ALINHAMENTO ATÉ A CAIXA DA AV. CLEMENTE CIFALI ESQUINA COM A RUA CAÍ, ONDE USAMOS A FIBRA 01 DO 24 NOVO COM A FIBRA 02 DO 24 F.O QUE VAI PARA A CAIXA DO SPLITTER 1X4 DA AV. FREDERICO AUGUSTO RITTER. APÓS CONCLUIR O ALINHAMENTO FIZEMOS A TROCA DAS ROTAS.\nlANÇADO 150 METROS DE CABO DE 24FO, 4 ABERTURA E FECHAMENTO, 2 CAIXAS NOVAS, 1 DERIVAÇÃO, 50 FUSÕES",
